using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor.SceneManagement;using Racer;
public static class InspectShortcutContacts{public static string Main(){EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardForward.unity");Physics.SyncTransforms();var lines=new List<string>();foreach(var b in UnityEngine.Object.FindObjectsByType<WoodlandRoute>()){for(float s=0;s<b.Length;s+=2){var p=b.At(s,out var f);var hits=Physics.OverlapBox(p+Vector3.up*.7f,new Vector3(.8f,.4f,1.3f),Quaternion.LookRotation(f));foreach(var c in hits)if(!c.name.Contains("timber collision")&&!c.name.StartsWith("Ground_")&&!c.name.Contains("resting platform"))lines.Add($"{b.title} s={s:F1} at={p} hit={c.name} centre={c.bounds.center}");}}File.WriteAllLines("Docs/BackyardShortcuts/contacts.txt",lines);return string.Join("\n",lines.Take(35));}}
